"""Origin framing and evidence audit extension.

The audit reads the concatenated parts of a capture as one HTTP/1.1 byte
stream, publishes the fully framed requests, attributes every request byte to
the capture part that supplied it and derives the paired evidence flags.
"""
import bisect
import re

from modules.byte_program import (hash_range, leaf, merge, read_range,
                                   fingerprint_bytes, MAX)

TOKEN = re.compile(rb"[!#$%&'*+.^_`|~0-9A-Za-z-]+\Z")

_MOD = 1 << 64
_MASK = _MOD - 1
_BASE = 257

MAX_REQUESTS = 20000
MAX_CHUNK_LINES = 40000
MAX_LINE = 8192
MAX_BLOCK = 65536
MAX_FIELDS = 128

_FORBIDDEN_TRAILER = (b'host', b'content-length', b'transfer-encoding')


class _Syntax(Exception):
    """Malformed capture bytes."""


class _Incomplete(Exception):
    """Capture bytes ended before the request was complete."""


class _Budget(object):
    """Shared audit budgets across all channels."""

    __slots__ = ('requests', 'chunk_lines')

    def __init__(self):
        self.requests = 0
        self.chunk_lines = 0

    def count_request(self):
        self.requests += 1
        if self.requests > MAX_REQUESTS:
            raise ValueError('request budget')

    def count_chunk_line(self):
        self.chunk_lines += 1
        if self.chunk_lines > MAX_CHUNK_LINES:
            raise ValueError('chunk line budget')


class _Hasher(object):
    """Incremental exact checksum of a byte sequence."""

    __slots__ = ('value', 'length')

    def __init__(self):
        self.value = 0
        self.length = 0

    def add_bytes(self, data):
        value = 0
        for byte in data:
            value = (value * _BASE + byte + 1) & _MASK
        self.value = (self.value * pow(_BASE, len(data), _MOD) + value) & _MASK
        self.length += len(data)

    def add_range(self, node, low, high):
        if high <= low:
            return
        segment = hash_range(node, low, high)
        self.value = (self.value * pow(_BASE, high - low, _MOD) + segment) & _MASK
        self.length += high - low

    def result(self):
        return {'n': self.length, 'h': '%016x' % self.value}


def _fields_fingerprint(fields):
    """Fingerprint of a field block: pair count then name/value pairs."""
    hasher = _Hasher()
    hasher.add_bytes(len(fields).to_bytes(8, 'big'))
    for name, value in fields:
        hasher.add_bytes(len(name).to_bytes(8, 'big'))
        hasher.add_bytes(name)
        hasher.add_bytes(len(value).to_bytes(8, 'big'))
        hasher.add_bytes(value)
    return hasher.result()


def _read_line(node, total, position):
    """Read one CRLF terminated line, returning ``(content, next_position)``."""
    remaining = total - position
    window = min(remaining, MAX_LINE + 2)
    data = read_range(node, position, position + window)
    index = data.find(b'\n')
    if index < 0:
        if remaining <= MAX_LINE + 1:
            raise _Incomplete()
        raise _Syntax()
    if index > MAX_LINE + 1:
        raise _Syntax()
    if index == 0 or data[index - 1] != 13:
        raise _Syntax()
    return data[:index - 1], position + index + 1


def _parse_field(line):
    """Split one header or trailer line into ``(name, trimmed_value)``."""
    index = line.find(b':')
    if index <= 0:
        raise _Syntax()
    name = line[:index]
    if TOKEN.match(name) is None:
        raise _Syntax()
    value = line[index + 1:]
    for byte in value:
        if byte == 9:
            continue
        if byte < 0x20 or byte > 0x7e:
            raise _Syntax()
    return name, value.strip(b' \t')


def _parse_chunk_size(line):
    """Parse one chunk size line."""
    index = line.find(b';')
    if index >= 0:
        digits = line[:index]
        suffix = line[index + 1:]
        for byte in suffix:
            if byte == 9:
                continue
            if byte < 0x20 or byte > 0x7e:
                raise _Syntax()
    else:
        digits = line
    if not digits:
        raise _Syntax()
    for byte in digits:
        if not (48 <= byte <= 57 or 97 <= byte <= 102 or 65 <= byte <= 70):
            raise _Syntax()
    value = int(digits, 16)
    if value > MAX:
        raise _Syntax()
    return value


def _owner_spans(offsets, ends, start, end):
    """Owner labels and positive byte counts overlapping ``[start,end)``."""
    spans = []
    index = bisect.bisect_right(ends, start)
    for position in range(index, len(offsets)):
        low, high, owner = offsets[position]
        if low >= end:
            break
        first = low if low > start else start
        last = high if high < end else end
        if last > first:
            spans.append((owner, last - first))
    return spans


def _merge_spans(spans):
    """Merge equal labels, keeping the order of their first occurrence."""
    order = []
    counts = {}
    for label, count in spans:
        if label in counts:
            counts[label] += count
        else:
            counts[label] = count
            order.append(label)
    return [[label, counts[label]] for label in order]


def _parse_request(node, total, position, budget, offsets, ends,
                   expect_by_name, request_frames, owner_counts, per_case):
    """Parse one HTTP/1.1 request, returning ``(record, next_position)``."""
    start = position
    line, position = _read_line(node, total, position)
    block_size = len(line) + 2
    if block_size > MAX_BLOCK:
        raise _Syntax()
    first = line.find(b' ')
    if first <= 0:
        raise _Syntax()
    second = line.find(b' ', first + 1)
    if second < 0:
        raise _Syntax()
    method = line[:first]
    target = line[first + 1:second]
    version = line[second + 1:]
    if version != b'HTTP/1.1':
        raise _Syntax()
    if TOKEN.match(method) is None:
        raise _Syntax()
    if not target:
        raise _Syntax()
    for byte in target:
        if byte < 0x21 or byte > 0x7e:
            raise _Syntax()

    fields = []
    while True:
        line, position = _read_line(node, total, position)
        block_size += len(line) + 2
        if block_size > MAX_BLOCK:
            raise _Syntax()
        if not line:
            break
        if len(fields) >= MAX_FIELDS:
            raise _Syntax()
        fields.append(_parse_field(line))

    lengths = []
    encoding_count = 0
    encoding_value = b''
    host_count = 0
    host_value = b''
    for name, value in fields:
        lowered = name.lower()
        if lowered == b'content-length':
            lengths.append(value)
        elif lowered == b'transfer-encoding':
            encoding_count += 1
            encoding_value = value
        elif lowered == b'host':
            host_count += 1
            host_value = value

    if encoding_count:
        if encoding_count > 1 or lengths:
            raise _Syntax()
        if encoding_value.strip(b' \t').lower() != b'chunked':
            raise _Syntax()
        framing = 'chunked'
        body_length = 0
    elif lengths:
        declared = set()
        for value in lengths:
            for member in value.split(b','):
                member = member.strip(b' \t')
                if not member or not member.isdigit():
                    raise _Syntax()
                number = int(member)
                if number > MAX:
                    raise _Syntax()
                declared.add(number)
        if len(declared) != 1:
            raise _Syntax()
        body_length = declared.pop()
        framing = 'length'
    else:
        body_length = 0
        framing = 'none'

    trailers = []
    if framing == 'length':
        if total - position < body_length:
            raise _Incomplete()
        body = _Hasher()
        body.add_range(node, position, position + body_length)
        position += body_length
        body_result = body.result()
    elif framing == 'chunked':
        body = _Hasher()
        while True:
            line, position = _read_line(node, total, position)
            budget.count_chunk_line()
            size = _parse_chunk_size(line)
            if size == 0:
                break
            if total - position < size:
                raise _Incomplete()
            body.add_range(node, position, position + size)
            position += size
            if total - position < 2:
                raise _Incomplete()
            if read_range(node, position, position + 2) != b'\r\n':
                raise _Syntax()
            position += 2
        body_result = body.result()
        block_size = 0
        while True:
            line, position = _read_line(node, total, position)
            block_size += len(line) + 2
            if block_size > MAX_BLOCK:
                raise _Syntax()
            if not line:
                break
            if len(trailers) >= MAX_FIELDS:
                raise _Syntax()
            name, value = _parse_field(line)
            if name.lower() in _FORBIDDEN_TRAILER:
                raise _Syntax()
            trailers.append((name, value))
    else:
        body_result = _Hasher().result()

    end = position
    spans = _owner_spans(offsets, ends, start, end)
    owner = spans[0][0] if spans else None
    owners = _merge_spans(spans)

    flags = set()
    if owner is None:
        flags.add('unattributed')
    for label, _count in spans:
        if label != owner:
            flags.add('mixed_owner')
            break
    if host_count == 0:
        flags.add('missing_host')
    elif host_count > 1:
        flags.add('multiple_host')
    if owner is not None:
        expect = expect_by_name.get(owner)
        if expect is not None:
            mismatch = (method != expect['method'].encode('ascii')
                        or target != expect['target'].encode('ascii')
                        or host_count != 1
                        or host_value.lower() != expect['host'].encode('ascii').lower())
            if mismatch:
                flags.add('identity')
        seen = owner_counts.get(owner, 0) + 1
        owner_counts[owner] = seen
        if seen > 1:
            flags.add('extra')
        if request_frames.get(owner, 0) == 0:
            flags.add('unsent')
        info = per_case.get(owner)
        if info is not None:
            info['origin_count'] += 1
            if 'identity' in flags:
                info['identity'] = True
            if 'mixed_owner' in flags:
                info['mixed'] = True

    record = {'start': start, 'end': end,
              'method': fingerprint_bytes(method),
              'target': fingerprint_bytes(target),
              'host': fingerprint_bytes(host_value.lower() if host_count == 1 else b''),
              'host_count': host_count,
              'headers': _fields_fingerprint(fields),
              'body': body_result,
              'trailers': _fields_fingerprint(trailers),
              'framing': framing,
              'owner': owner,
              'owners': owners,
              'flags': sorted(flags)}
    return record, end


def _audit_channel(channel, expect_by_name, request_frames, owner_counts, budget, per_case):
    """Audit one capture channel."""
    offsets = []
    node = None
    position = 0
    for part in channel['parts']:
        data = part['data']
        node = merge(node, data)
        offsets.append((position, position + data.length, part['case']))
        position += data.length
    total = position
    ends = [entry[1] for entry in offsets]

    requests = []
    error = None
    position = 0
    while position < total:
        try:
            record, position = _parse_request(node, total, position, budget, offsets,
                                              ends, expect_by_name, request_frames,
                                              owner_counts, per_case)
        except _Incomplete:
            error = {'kind': 'incomplete', 'offset': position}
            break
        except _Syntax:
            error = {'kind': 'syntax', 'offset': position}
            break
        budget.count_request()
        requests.append(record)

    boundaries = [entry['end'] for entry in requests]
    committed = [bisect.bisect_right(boundaries, entry[1]) for entry in offsets]

    return {'name': channel['name'],
            'bytes': {'n': total, 'h': _channel_hash(node)},
            'requests': requests,
            'committed': committed,
            'error': error}


def _channel_hash(node):
    """Exact checksum of the whole capture."""
    if node is None:
        return 0
    return node.hash


def audit_channels(channels, cases, sent):
    """Audit every channel and return the channel records plus case evidence."""
    expect_by_name = {}
    for case in cases:
        expect_by_name[case['name']] = case['expect']
    request_frames = {}
    for record in sent:
        request_frames[record['name']] = record['request_frames']
    per_case = {}
    for name in expect_by_name:
        per_case[name] = {'origin_count': 0, 'identity': False, 'mixed': False}
    budget = _Budget()
    owner_counts = {}
    records = []
    for channel in channels:
        records.append(_audit_channel(channel, expect_by_name, request_frames,
                                      owner_counts, budget, per_case))
    return records, per_case
